import json

L = [71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64]
L_set = set(L)

# generate all valid triples (a,b,c) with a<b and a+b=c
triples = []
for i in range(len(L)):
    for j in range(i+1, len(L)):
        a = L[i]
        b = L[j]
        c = a + b
        if c in L_set:
            triples.append((a, b, c))

# backtrack exact cover
used = set()
solution = []

def backtrack(start):
    if len(solution) == 15:
        return True
    # pick a number not used yet
    for idx in range(start, len(triples)):
        a, b, c = triples[idx]
        if a in used or b in used or c in used:
            continue
        # choose this triple
        solution.append((a, b, c))
        used.update([a, b, c])
        if backtrack(0):
            return True
        # undo
        solution.pop()
        used.difference_update([a, b, c])
    return False

found = backtrack(0)
if found:
    witness = {
        "polarity": "positive",
        "data": {
            "partition": solution
        },
        "basis": None
    }
else:
    witness = {
        "polarity": "negative",
        "basis": "search",
        "search_exhausted": True,
        "nodes_explored": None,
        "method": "backtrack"
    }
print("WITNESS: " + json.dumps(witness))

import re

# Token specification
TOKEN_SPEC = [
    ("NUMBER",   r"\d+(?:\.\d*)?|\.\d+"),
    ("PLUS",     r"\+"),
    ("MINUS",    r"-"),
    ("MUL",      r"\*"),
    ("DIV",      r"/"),
    ("LPAREN",   r"\("),
    ("RPAREN",   r"\)"),
    ("SKIP",     r"[ \t]+"),
    ("MISMATCH", r"."),
]

Token = tuple  # (type, value)

class Lexer:
    def __init__(self, text):
        self.text = text
        self.tokens = self._generate_tokens()
        self.current = None
        self._advance()

    def _generate_tokens(self):
        pattern = "|".join(f"(?P<{name}>{regex})" for name, regex in TOKEN_SPEC)
        scanner = re.compile(pattern)
        for mo in scanner.finditer(self.text):
            kind = mo.lastgroup
            value = mo.group()
            if kind == "NUMBER":
                yield ("NUMBER", float(value) if "." in value else int(value))
            elif kind == "SKIP":
                continue
            elif kind == "MISMATCH":
                raise SyntaxError(f"Unexpected character '{value}'")
            else:
                yield (kind, value)
        yield ("EOF", None)

    def _advance(self):
        try:
            self.current = next(self.tokens)
        except StopIteration:
            self.current = ("EOF", None)

    def peek(self):
        return self.current[0]

    def consume(self, token_type):
        if self.current[0] == token_type:
            val = self.current[1]
            self._advance()
            return val
        else:
            raise SyntaxError(f"Expected token {token_type} but got {self.current[0]}")

class Parser:
    def __init__(self, lexer):
        self.lexer = lexer

    def parse(self):
        result = self.expr()
        if self.lexer.peek() != "EOF":
            raise SyntaxError("Extra characters after valid expression")
        return result

    # expr -> term ((PLUS|MINUS) term)*
    def expr(self):
        value = self.term()
        while self.lexer.peek() in ("PLUS", "MINUS"):
            op = self.lexer.peek()
            self.lexer._advance()
            right = self.term()
            if op == "PLUS":
                value = value + right
            else:
                value = value - right
        return value

    # term -> factor ((MUL|DIV) factor)*
    def term(self):
        value = self.factor()
        while self.lexer.peek() in ("MUL", "DIV"):
            op = self.lexer.peek()
            self.lexer._advance()
            right = self.factor()
            if op == "MUL":
                value = value * right
            else:
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                value = value / right
        return value

    # factor -> MINUS factor | PLUS factor | NUMBER | LPAREN expr RPAREN
    def factor(self):
        token_type = self.lexer.peek()
        if token_type == "PLUS":
            self.lexer._advance()
            return self.factor()
        if token_type == "MINUS":
            self.lexer._advance()
            return -self.factor()
        if token_type == "NUMBER":
            return self.lexer.consume("NUMBER")
        if token_type == "LPAREN":
            self.lexer._advance()
            value = self.expr()
            if self.lexer.peek() != "RPAREN":
                raise SyntaxError("Unmatched '('")
            self.lexer._advance()
            return value
        raise SyntaxError(f"Unexpected token {token_type}")

def evaluate(expression: str):
    """Parse and evaluate arithmetic expression.
    Raises SyntaxError for malformed input and ZeroDivisionError for division by zero.
    """
    lexer = Lexer(expression)
    parser = Parser(lexer)
    return parser.parse()

# Test suite
def _assert_equal(a, b, eps=1e-9):
    if isinstance(a, float) or isinstance(b, float):
        assert abs(a - b) < eps, f"{a} != {b}"
    else:
        assert a == b, f"{a} != {b}"

def run_tests():
    # Positive tests
    _assert_equal(evaluate("3 + 4 * 2"), 11)
    _assert_equal(evaluate("-(3 + 4) * 2"), -14)
    _assert_equal(evaluate("10 / 3"), 10/3)
    _assert_equal(evaluate("(1 + 2) * (3 + 4)"), 21)
    _assert_equal(evaluate("-5 + 3"), -2)
    _assert_equal(evaluate("- ( - 3 )"), 3)

    # Error tests
    error_cases = [
        ("3 + ", "Expected token NUMBER but got EOF"),
        ("(1 + 2", "Unmatched '('"),
        ("4 ** 2", "Unexpected character '*'")
    ]
    for expr, msg in error_cases:
        try:
            evaluate(expr)
            assert False, f"Expression '{expr}' should have failed"
        except Exception as e:
            assert msg in str(e), f"Unexpected error message for '{expr}': {e}"

if __name__ == "__main__":
    run_tests()
    print("All tests passed.")

import re

class Lexer:
    TOKEN_SPEC = [
        ('NUMBER',   r'\d+(?:\.\d*)?|\.\d+'),
        ('PLUS',     r'\+'),
        ('MINUS',    r'-'),
        ('TIMES',    r'\*'),
        ('DIVIDE',   r'/'),
        ('LPAREN',   r'\('),
        ('RPAREN',   r'\)'),
        ('SKIP',     r'[ \t]+'),
        ('MISMATCH', r'.'),
    ]
    def __init__(self, text):
        self.text = text
        self.tokens = self.tokenize(text)
        self.pos = 0
    def tokenize(self, text):
        token_regex = '|'.join('(?P<%s>%s)' % pair for pair in self.TOKEN_SPEC)
        get_token = re.compile(token_regex).match
        pos = 0
        tokens = []
        while pos < len(text):
            m = get_token(text, pos)
            if not m:
                raise SyntaxError(f'Unexpected character at position {pos}')
            typ = m.lastgroup
            if typ == 'NUMBER':
                val = float(m.group(typ))
                tokens.append(('NUMBER', val))
            elif typ == 'SKIP':
                pass
            elif typ == 'MISMATCH':
                raise SyntaxError(f'Unexpected token {m.group(typ)!r} at position {pos}')
            else:
                tokens.append((typ, m.group(typ)))
            pos = m.end()
        tokens.append(('EOF', None))
        return tokens
    def peek(self):
        return self.tokens[self.pos]
    def advance(self):
        self.pos += 1
    def expect(self, token_type):
        typ, val = self.peek()
        if typ != token_type:
            raise SyntaxError(f'Expected {token_type} but found {typ}')
        self.advance()
        return val

class Parser:
    def __init__(self, lexer):
        self.lexer = lexer
    def parse(self):
        result = self.expr()
        if self.lexer.peek()[0] != 'EOF':
            raise SyntaxError('Unexpected token after end of expression')
        return result
    # expr -> term ((PLUS|MINUS) term)*
    def expr(self):
        left = self.term()
        while True:
            typ, _ = self.lexer.peek()
            if typ == 'PLUS':
                self.lexer.advance()
                right = self.term()
                left = left + right
            elif typ == 'MINUS':
                self.lexer.advance()
                right = self.term()
                left = left - right
            else:
                break
        return left
    # term -> factor ((TIMES|DIVIDE) factor)*
    def term(self):
        left = self.factor()
        while True:
            typ, _ = self.lexer.peek()
            if typ == 'TIMES':
                self.lexer.advance()
                right = self.factor()
                left = left * right
            elif typ == 'DIVIDE':
                self.lexer.advance()
                right = self.factor()
                if right == 0:
                    raise ZeroDivisionError('division by zero')
                left = left / right
            else:
                break
        return left
    # factor -> MINUS factor | primary
    def factor(self):
        typ, _ = self.lexer.peek()
        if typ == 'MINUS':
            self.lexer.advance()
            return -self.factor()
        return self.primary()
    # primary -> NUMBER | LPAREN expr RPAREN
    def primary(self):
        typ, val = self.lexer.peek()
        if typ == 'NUMBER':
            self.lexer.advance()
            return val
        if typ == 'LPAREN':
            self.lexer.advance()
            inner = self.expr()
            if self.lexer.peek()[0] != 'RPAREN':
                raise SyntaxError('Unmatched parentheses')
            self.lexer.advance()
            return inner
        raise SyntaxError(f'Unexpected token {typ}')

def evaluate(expr):
    lexer = Lexer(expr)
    parser = Parser(lexer)
    return parser.parse()

def run_tests():
    # Correct evaluations
    assert abs(evaluate('3 + 4 * 2') - 11) < 1e-9
    assert abs(evaluate('-(3 + 4) * 2') + 14) < 1e-9
    assert abs(evaluate('10 / 3') - (10/3)) < 1e-9
    # Error cases
    error_cases = [
        ('3 + ', 'Expected NUMBER'),
        ('(1 + 2', 'Unmatched parentheses'),
        ('* 5', 'Unexpected token MINUS'),
    ]
    for expr, msg in error_cases:
        try:
            evaluate(expr)
            assert False, f'Expression {expr!r} should have failed'
        except Exception as e:
            assert msg in str(e), f'Expected message containing {msg!r}, got {e}'
    print('All tests passed')

if __name__ == '__main__':
    run_tests()

import json
from itertools import combinations

L = [71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64]

# Pre‑compute all possible pairs and the sum they produce
pair_sum = {}
for a, b in combinations(L, 2):
    s = a + b
    if s in L:  # only keep sums that are also in the list
        pair_sum.setdefault(s, []).append((a, b))

# Sort sums to try smaller search tree first
sums_order = sorted(pair_sum.keys())

used = set()
solution = []

def backtrack():
    if len(used) == len(L):
        return True
    # find next unused sum candidate
    for c in sums_order:
        if c in used:
            continue
        for a, b in pair_sum[c]:
            if a in used or b in used:
                continue
            # choose this triple
            used.update([a, b, c])
            solution.append((a, b, c))
            if backtrack():
                return True
            # backtrack
            used.difference_update([a, b, c])
            solution.pop()
    return False

found = backtrack()
if found:
    witness = {
        "polarity": "positive",
        "data": {
            "triples": solution
        }
    }
    print("WITNESS: " + json.dumps(witness))
else:
    witness = {
        "polarity": "negative",
        "basis": "search",
        "search_exhausted": True,
        "nodes_explored": None,
        "method": "depth‑first backtracking"
    }
    print("WITNESS: " + json.dumps(witness))

import json, sys
L = [71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64]
L_set = set(L)
# map each possible c to list of (a,b) pairs with a+b=c
sum_to_pairs = {}
for i, a in enumerate(L):
    for b in L[i+1:]:
        s = a + b
        if s in L_set:
            sum_to_pairs.setdefault(s, []).append((a, b))

used = set()
solution = []

def backtrack():
    if len(used) == len(L):
        return True
    # choose next unused c that has candidate pairs
    for c in L:
        if c in used:
            continue
        candidates = sum_to_pairs.get(c, [])
        # filter candidates where a,b unused
        for a, b in candidates:
            if a in used or b in used:
                continue
            # use them
            used.update([a, b, c])
            solution.append((a, b, c))
            if backtrack():
                return True
            # backtrack
            used.difference_update([a, b, c])
            solution.pop()
        # if no candidate works for this c, dead end
        return False
    return False

found = backtrack()
if found:
    witness = {
        "polarity": "positive",
        "data": {"triples": solution},
        "basis": None
    }
    print("WITNESS: " + json.dumps(witness))
else:
    # No solution found; report negative witness with search info
    witness = {
        "polarity": "negative",
        "basis": "search",
        "search_exhausted": True,
        "nodes_explored": None,
        "method": "depth‑first backtracking"
    }
    print("WITNESS: " + json.dumps(witness))
